        test('Create catalog item with reference qualifier variables', async () => {
            const project = createProject({ config: { scope: SCOPE } })

            // Read the fluent file
            const fluentCode = fs.readFileSync(
                path.resolve(__dirname, '../fluent/catalog-item-variables/create/reference.now.ts'),
                'utf-8'
            )

            // Register IDs
            const catalogItemId = project.registerExplicitId('sc_cat_item', 'reference_test_item')

            // Add file
            const file = project.addFile({
                path: 'catalog-item-reference-variable.now.ts',
                content: fluentCode,
            })

            // Process
            const output = await file.getOutput()

            // Should have: 1 catalog item + 1 catalog M2M + 4 reference variables = 6 files
            expect(output.length).toEqual(6)

            // Verify catalog item
            const catalogItemXml = output.find((x) => x.path.includes(`sc_cat_item_${catalogItemId}`))
            expect(catalogItemXml).toBeDefined()
            expect(catalogItemXml.content).toContain('<name>Reference Test</name>')
            expect(catalogItemXml.content).toContain('<short_description>Test reference variables</short_description>')

            // Test 1: Simple Reference with referenceQual
            const simpleRefVarId = project.registerCoalesceId('item_option_new', {
                cat_item: catalogItemId,
                name: 'simpleRef',
            })
            const simpleRefXml = output.find((x) => x.path.includes(`item_option_new_${simpleRefVarId}`))
            expect(simpleRefXml).toBeDefined()
            expect(simpleRefXml.content).toContain('<name>simpleRef</name>')
            expect(simpleRefXml.content).toContain('<question_text>Simple Reference</question_text>')
            expect(simpleRefXml.content).toContain('<type>8</type>')
            expect(simpleRefXml.content).toContain('<reference>sys_user</reference>')
            expect(simpleRefXml.content).toContain('<reference_qual_condition>active=true</reference_qual_condition>')
            expect(simpleRefXml.content).toContain('<use_reference_qualifier>simple</use_reference_qualifier>')

            // Test 2: Dynamic Reference with dynamicRefQual
            const dynamicRefVarId = project.registerCoalesceId('item_option_new', {
                cat_item: catalogItemId,
                name: 'dynamicRef',
            })
            const dynamicRefXml = output.find((x) => x.path.includes(`item_option_new_${dynamicRefVarId}`))
            expect(dynamicRefXml).toBeDefined()
            expect(dynamicRefXml.content).toContain('<name>dynamicRef</name>')
            expect(dynamicRefXml.content).toContain('<question_text>Dynamic Reference</question_text>')
            expect(dynamicRefXml.content).toContain('<type>8</type>')
            expect(dynamicRefXml.content).toContain('<reference>sys_user</reference>')
            expect(dynamicRefXml.content).toContain('<use_reference_qualifier>dynamic</use_reference_qualifier>')
            expect(dynamicRefXml.content).toContain(
                '<dynamic_ref_qual>c5056264d711210032d7a3b20e610375</dynamic_ref_qual>'
            )

            // Test 3: Advanced Reference with useReferenceQualifier
            const advancedRefVarId = project.registerCoalesceId('item_option_new', {
                cat_item: catalogItemId,
                name: 'advancedRef',
            })
            const advancedRefXml = output.find((x) => x.path.includes(`item_option_new_${advancedRefVarId}`))
            expect(advancedRefXml).toBeDefined()
            expect(advancedRefXml.content).toContain('<name>advancedRef</name>')
            expect(advancedRefXml.content).toContain('<question_text>Advanced Reference</question_text>')
            expect(advancedRefXml.content).toContain('<type>8</type>')
            expect(advancedRefXml.content).toContain('<reference>sys_user</reference>')
            expect(advancedRefXml.content).toContain('<use_reference_qualifier>advanced</use_reference_qualifier>')
            expect(advancedRefXml.content).toContain('<reference_qual>active=true</reference_qual>')

            // Test 4: RequestedFor Variable with special properties
            const requestedForVarId = project.registerCoalesceId('item_option_new', {
                cat_item: catalogItemId,
                name: 'requestedFor',
            })
            const requestedForXml = output.find((x) => x.path.includes(`item_option_new_${requestedForVarId}`))
            expect(requestedForXml).toBeDefined()
            expect(requestedForXml.content).toContain('<name>requestedFor</name>')
            expect(requestedForXml.content).toContain('<question_text>Requested For</question_text>')
            expect(requestedForXml.content).toContain('<type>31</type>')
            expect(requestedForXml.content).toContain('<reference>sys_user</reference>')
            expect(requestedForXml.content).toContain(
                '<reference_qual_condition>active=true</reference_qual_condition>'
            )
            expect(requestedForXml.content).toContain('<enable_also_request_for>true</enable_also_request_for>')
            expect(requestedForXml.content).toContain(
                '<roles_to_use_also_request_for>admin,itil</roles_to_use_also_request_for>'
            )
        })
        test('Create catalog item with checkbox pricing variables', async () => {
            const project = createProject({ config: { scope: SCOPE } })

            // Read the fluent file
            const fluentCode = fs.readFileSync(
                path.resolve(__dirname, '../fluent/catalog-item-variables/create/checkbox.now.ts'),
                'utf-8'
            )

            // Register IDs
            const catalogItemId = project.registerExplicitId('sc_cat_item', 'checkbox_pricing_test')

            // Add file
            const file = project.addFile({
                path: 'catalog-item-checkbox.now.ts',
                content: fluentCode,
            })

            // Process
            const output = await file.getOutput()

            // Should have: 1 catalog item + 1 catalog M2M + 3 checkbox variables + 3 pricing records = 8 files
            expect(output.length).toEqual(8)

            // Verify catalog item
            const catalogItemXml = output.find((x) => x.path.includes(`sc_cat_item_${catalogItemId}`))
            expect(catalogItemXml).toBeDefined()
            expect(catalogItemXml.content).toContain('<name>Checkbox Pricing Test</name>')

            // Test 1: Checkbox with multiple pricing details (one-time and recurring)
            const premiumSupportVarId = project.registerCoalesceId('item_option_new', {
                cat_item: catalogItemId,
                name: 'premiumSupport',
            })
            const premiumSupportXml = output.find((x) => x.path.includes(`item_option_new_${premiumSupportVarId}`))
            expect(premiumSupportXml).toBeDefined()
            expect(premiumSupportXml.content).toContain('<name>premiumSupport</name>')
            expect(premiumSupportXml.content).toContain('<question_text>Premium Support</question_text>')
            expect(premiumSupportXml.content).toContain('<type>7</type>')
            expect(premiumSupportXml.content).toContain('<order>1</order>')

            // Verify one-time price for premium support
            const premiumPriceId = project.registerCoalesceId('fx_price', {
                id: premiumSupportVarId,
                field: 'price_if_checked',
            })
            const premiumPriceXml = output.find((x) => x.path.includes(`fx_price_${premiumPriceId}`))
            expect(premiumPriceXml).toBeDefined()
            expect(premiumPriceXml.content).toContain(`<id>${premiumSupportVarId}</id>`)
            expect(premiumPriceXml.content).toContain('<field>price_if_checked</field>')
            expect(premiumPriceXml.content).toContain('<amount>100</amount>')
            expect(premiumPriceXml.content).toContain('<currency>USD</currency>')

            // Verify recurring price for premium support
            const premiumRecPriceId = project.registerCoalesceId('fx_price', {
                id: premiumSupportVarId,
                field: 'rec_price_if_checked',
            })
            const premiumRecPriceXml = output.find((x) => x.path.includes(`fx_price_${premiumRecPriceId}`))
            expect(premiumRecPriceXml).toBeDefined()
            expect(premiumRecPriceXml.content).toContain(`<id>${premiumSupportVarId}</id>`)
            expect(premiumRecPriceXml.content).toContain('<field>rec_price_if_checked</field>')
            expect(premiumRecPriceXml.content).toContain('<amount>50</amount>')
            expect(premiumRecPriceXml.content).toContain('<currency>GBP</currency>')
            expect(premiumRecPriceXml.content).toContain('<type>calculated</type>')

            // Test 2: Checkbox with single pricing detail (EUR)
            const extendedWarrantyVarId = project.registerCoalesceId('item_option_new', {
                cat_item: catalogItemId,
                name: 'extendedWarranty',
            })
            const extendedWarrantyXml = output.find((x) => x.path.includes(`item_option_new_${extendedWarrantyVarId}`))
            expect(extendedWarrantyXml).toBeDefined()
            expect(extendedWarrantyXml.content).toContain('<name>extendedWarranty</name>')
            expect(extendedWarrantyXml.content).toContain('<question_text>Extended Warranty</question_text>')
            expect(extendedWarrantyXml.content).toContain('<type>7</type>')

            const warrantyPriceId = project.registerCoalesceId('fx_price', {
                id: extendedWarrantyVarId,
                field: 'price_if_checked',
            })
            const warrantyPriceXml = output.find((x) => x.path.includes(`fx_price_${warrantyPriceId}`))
            expect(warrantyPriceXml).toBeDefined()
            expect(warrantyPriceXml.content).toContain('<amount>200</amount>')
            expect(warrantyPriceXml.content).toContain('<currency>EUR</currency>')

            // Test 3: Checkbox without pricing
            const rushDeliveryVarId = project.registerCoalesceId('item_option_new', {
                cat_item: catalogItemId,
                name: 'rushDelivery',
            })
            const rushDeliveryXml = output.find((x) => x.path.includes(`item_option_new_${rushDeliveryVarId}`))
            expect(rushDeliveryXml).toBeDefined()
            expect(rushDeliveryXml.content).toContain('<name>rushDelivery</name>')
            expect(rushDeliveryXml.content).toContain('<question_text>Rush Delivery</question_text>')
            expect(rushDeliveryXml.content).toContain('<type>7</type>')

            // Verify no pricing records for rushDelivery
            const rushPriceRecords = output.filter(
                (x) => x.content.includes(rushDeliveryVarId) && x.path.includes('fx_price')
            )
            expect(rushPriceRecords).toHaveLength(0)
        })
